using System.Text;using System.Text.Json;using System.Text.Json.Nodes;using Experiments;
namespace Experiments.Tests;
public sealed record TestCase(string Name,bool Passed,string? Error);
public sealed record TestReport(int Passed,int Failed,TestCase[] Results,string Backend);
public static class TestSuite
{
 public static ExperimentSpec Spec(string endpoint)=>new(endpoint,"synthetic/model","Explain one controlled experiment.","Return a short test response.",TimeoutMilliseconds:3000,BackendLabel:"controlled loopback stub; no LM Studio inference");
 public static async Task<TestReport> RunAsync(string output)
 {
  Directory.CreateDirectory(output);var cases=new List<TestCase>();int index=0;
  string Folder()=>Path.Combine(output,(++index).ToString(System.Globalization.CultureInfo.InvariantCulture));
  void Assert(bool yes,string message="Unexpected result"){if(!yes)throw new InvalidOperationException(message);}
  async Task Test(string name,Func<Task> action){try{await action();cases.Add(new(name,true,null));}catch(Exception e){cases.Add(new(name,false,e.Message));}}
  async Task<BundleResult> Run(StubServer server,ExperimentSpec? spec=null,string token="",CancellationToken cancel=default)=>await new ExperimentRunner().RunAsync(spec??Spec(server.Endpoint),Folder(),token,cancel);
  void Rehash(string directory,Action<JsonObject> mutation){string file=Path.Combine(directory,"manifest.json");var json=JsonNode.Parse(File.ReadAllText(file))!.AsObject();mutation(json);byte[] bytes=Data.Canonical(json);File.WriteAllBytes(file,bytes);File.WriteAllText(Path.Combine(directory,"manifest.sha256"),Data.Digest(bytes)+"  manifest.json\n");}
  await Test("loopback-only target validation",()=>{foreach(string target in new[]{"http://example.com/","http://192.0.2.1/","http://127.0.0.1/?secret=x","http://user:pass@127.0.0.1/","https://127.0.0.1/","http://127.0.0.1/path"}){bool blocked=false;try{Data.Endpoint(target);}catch(ArgumentException){blocked=true;}Assert(blocked,target);}Assert(Data.Endpoint("http://localhost:1234/").Host=="127.0.0.1");return Task.CompletedTask;});
  await Test("successful real HTTP load/chat workflow and unknown identities",async()=>{await using var stub=new StubServer();var r=await Run(stub);Assert(r.Outcome.State=="completed"&&stub.Requests==3);Assert(r.Outcome.LoadChecks.All(c=>c.Verdict=="match"));Assert(r.Outcome.Identity.ModelFileSha256.StartsWith("unknown")&&r.Outcome.Identity.RuntimeEngineVersion.StartsWith("unknown"));Assert(BundleStore.Verify(r.Directory,r.Digest).Valid);});
  await Test("stored exact request bytes equal transmitted body",async()=>{await using var stub=new StubServer();var r=await Run(stub);Assert(stub.LastChatRequest!.SequenceEqual(File.ReadAllBytes(Path.Combine(r.Directory,"chat-request.json"))));var chat=JsonNode.Parse(stub.LastChatRequest)!;Assert(chat["store"]!.GetValue<bool>()==false&&chat["stream"]!.GetValue<bool>()==false);});
  await Test("API authorization sent but not persisted; error body redacted",async()=>{await using var stub=new StubServer{Mode="error"};const string token="synthetic-credential-4a82";var r=await Run(stub,token:token);Assert(stub.LastAuthorization=="Bearer "+token);Assert(r.Outcome.State=="failed");foreach(string file in Directory.EnumerateFiles(r.Directory))Assert(!File.ReadAllText(file).Contains(token,StringComparison.Ordinal));Assert(File.ReadAllText(Path.Combine(r.Directory,"models-response.json")).Contains("[REDACTED]"));});
  await Test("credentials in experiment payload rejected before network",async()=>{await using var stub=new StubServer();bool rejected=false;try{await Run(stub,Spec(stub.Endpoint)with{Prompt="synthetic-secret"},"synthetic-secret");}catch(ArgumentException){rejected=true;}Assert(rejected&&stub.Requests==0);});
  await Test("JSON-escaped credential rejected before network",async()=>{await using var stub=new StubServer();bool rejected=false;try{await Run(stub,Spec(stub.Endpoint)with{Prompt="synthetic\"credential"},"synthetic\"credential");}catch(ArgumentException){rejected=true;}Assert(rejected&&stub.Requests==0);});
  await Test("credential property names and nested values redacted",()=>{const string token="fixture-secret";var bytes=Data.Canonical(new JsonObject{[token]=new JsonArray(token),["access_token"]="synthetic"});var safe=Data.Redact(bytes,token);Assert(safe.Redacted&&!Encoding.UTF8.GetString(safe.Bytes).Contains(token));return Task.CompletedTask;});
  await Test("unstructured error body omitted before persistence",()=>{var safe=Data.Redact(Encoding.UTF8.GetBytes("invalid-json with fixture-secret"),"fixture-secret");Assert(safe.Redacted&&Encoding.UTF8.GetString(safe.Bytes).Contains("body_omitted")&&!Encoding.UTF8.GetString(safe.Bytes).Contains("fixture-secret"));return Task.CompletedTask;});
  await Test("server-applied load mismatch preserved and blocks replay",async()=>{await using var stub=new StubServer{Mode="echo-mismatch"};var s=Spec(stub.Endpoint);var r=await Run(stub,s);Assert(r.Outcome.State=="completed"&&r.Outcome.LoadChecks.Any(c=>c.Verdict=="different"));Assert(!BundleStore.ReplayGuard(r.Directory,s).ConfigurationReplayAllowed);});
  await Test("guarded replay rechecks live echo and stops before chat",async()=>{await using var stub=new StubServer{Mode="echo-mismatch"};var r=await new ExperimentRunner().RunAsync(Spec(stub.Endpoint),Folder(),requireMatchingLoadEcho:true);Assert(r.Outcome.State=="failed"&&stub.Requests==2&&stub.LastChatRequest is null&&r.Outcome.BackendCompletionUnknown);});
  await Test("missing load echo explicit unknown and blocks replay",async()=>{await using var stub=new StubServer{Mode="missing-echo"};var s=Spec(stub.Endpoint);var r=await Run(stub,s);Assert(r.Outcome.LoadChecks.All(c=>c.Verdict=="unknown"));Assert(!BundleStore.ReplayGuard(r.Directory,s).ConfigurationReplayAllowed);});
  await Test("numerically equal load echo representations match",async()=>{await using var stub=new StubServer{Mode="echo-float"};var r=await Run(stub);Assert(r.Outcome.LoadChecks.All(c=>c.Verdict=="match"));});
  await Test("timeout is client-only; backend may finish later",async()=>{await using var stub=new StubServer{Mode="slow"};var r=await Run(stub,Spec(stub.Endpoint)with{TimeoutMilliseconds=150});Assert(r.Outcome.State=="client_timeout"&&r.Outcome.BackendCompletionUnknown);await Task.Delay(550);Assert(stub.BackendFinishes==1,"Stub backend did not continue after client timeout");});
  await Test("cancellation distinct from timeout; incomplete replay blocked",async()=>{await using var stub=new StubServer{Mode="slow"};using var cancel=new CancellationTokenSource(120);var s=Spec(stub.Endpoint);var r=await Run(stub,s,cancel:cancel.Token);Assert(r.Outcome.State=="client_canceled"&&r.Outcome.BackendCompletionUnknown);Assert(!BundleStore.ReplayGuard(r.Directory,s).ConfigurationReplayAllowed);});
  await Test("HTTP redirects not followed",async()=>{await using var stub=new StubServer{Mode="redirect"};var r=await Run(stub);Assert(r.Outcome.State=="failed"&&stub.Requests==1);});
  await Test("malformed JSON retained as failed run",async()=>{await using var stub=new StubServer{Mode="malformed"};var r=await Run(stub);Assert(r.Outcome.State=="failed"&&BundleStore.Verify(r.Directory).Valid);});
  await Test("oversize response bounded and fails",async()=>{await using var stub=new StubServer{Mode="oversize"};var r=await Run(stub);Assert(r.Outcome.State=="failed"&&r.Outcome.Detail.Contains("2MiB"));});
  await Test("loaded/response instance mismatch blocks success",async()=>{await using var stub=new StubServer{Mode="instance-mismatch"};var r=await Run(stub);Assert(r.Outcome.State=="failed"&&r.Outcome.BackendCompletionUnknown);});
  await Test("one requested factor differs; no causal proof",async()=>{await using var stub=new StubServer();var s=Spec(stub.Endpoint);var a=await Run(stub,s);var b=await Run(stub,s with{Temperature=0.4});var diff=BundleStore.Compare(a.Directory,b.Directory);Assert(diff.ExactlyOneRequestedFactorChanged&&diff.RequestedChanges.Single().Path=="temperature");Assert(diff.CausalAttribution.Contains("Unknown"));});
  await Test("multiple requested changes not mislabeled one factor",async()=>{await using var stub=new StubServer();var s=Spec(stub.Endpoint);var a=await Run(stub,s);var b=await Run(stub,s with{Temperature=0.4,Prompt="Changed prompt"});Assert(!BundleStore.Compare(a.Directory,b.Directory).ExactlyOneRequestedFactorChanged);});
  await Test("configuration replay allowed with explicit unknown warnings",async()=>{await using var stub=new StubServer();var s=Spec(stub.Endpoint);var r=await Run(stub,s);var guard=BundleStore.ReplayGuard(r.Directory,s);Assert(guard.ConfigurationReplayAllowed&&guard.Warnings.Any(w=>w.Contains("unknown")));Assert(!BundleStore.ReplayGuard(r.Directory,s with{Temperature=0.8}).ConfigurationReplayAllowed);});
  await Test("plugin descriptors/tool response committed; automatic replay blocked",async()=>{await using var stub=new StubServer();var s=Spec(stub.Endpoint)with{IntegrationsJson="[{\"type\":\"plugin\",\"id\":\"mcp/synthetic\",\"allowed_tools\":[\"fixture\"]}]"};var r=await Run(stub,s);Assert(!BundleStore.ReplayGuard(r.Directory,s).ConfigurationReplayAllowed);Assert(File.ReadAllText(Path.Combine(r.Directory,"chat-request.json")).Contains("allowed_tools"));Assert(File.ReadAllText(Path.Combine(r.Directory,"chat-response.json")).Contains("tool_call"));});
  await Test("remote MCP declarations rejected",()=>{bool rejected=false;try{Data.Validate(Spec("http://127.0.0.1:1/")with{IntegrationsJson="[{\"type\":\"ephemeral_mcp\",\"server_url\":\"https://example.com/\"}]"});}catch(ArgumentException){rejected=true;}Assert(rejected);return Task.CompletedTask;});
  foreach(string name in new[]{"spec.json","chat-request.json","chat-response.json","outcome.json","manifest.json"})await Test("tamper detected: "+name,async()=>{await using var stub=new StubServer();var r=await Run(stub);File.AppendAllText(Path.Combine(r.Directory,name),"x");Assert(!BundleStore.Verify(r.Directory).Valid);});
  await Test("independent anchor detects fully rewritten manifest",async()=>{await using var stub=new StubServer();var r=await Run(stub);Rehash(r.Directory,n=>n["producer"]="rewritten");Assert(BundleStore.Verify(r.Directory).Valid);Assert(!BundleStore.Verify(r.Directory,r.Digest).Valid);});
  await Test("manifest path traversal rejected",async()=>{await using var stub=new StubServer();var r=await Run(stub);Rehash(r.Directory,n=>n["artifacts"]![0]!["name"]="../outside");Assert(!BundleStore.Verify(r.Directory).Valid);});
  await Test("extra uncommitted entry rejected",async()=>{await using var stub=new StubServer();var r=await Run(stub);File.WriteAllText(Path.Combine(r.Directory,"extra.txt"),"synthetic");Assert(!BundleStore.Verify(r.Directory).Valid);});
  await Test("export verifies copied exact artifacts and refuses overwrite",async()=>{await using var stub=new StubServer();var r=await Run(stub);string destination=Path.Combine(output,"exported");BundleStore.Export(r.Directory,destination);Assert(BundleStore.Verify(destination,r.Digest).Valid);bool blocked=false;try{BundleStore.Export(r.Directory,destination);}catch(IOException){blocked=true;}Assert(blocked);});
  await Test("artifact reader rejects traversal",async()=>{await using var stub=new StubServer();var r=await Run(stub);bool blocked=false;try{BundleStore.ReadArtifact<JsonObject>(r.Directory,"../outside");}catch(InvalidDataException){blocked=true;}Assert(blocked);});
  var report=new TestReport(cases.Count(c=>c.Passed),cases.Count(c=>!c.Passed),cases.ToArray(),"Controlled loopback TCP HTTP stub; no LM Studio process/model/ASR/private files accessed");File.WriteAllBytes(Path.Combine(output,"test-results.json"),Data.Bytes(report));return report;
 }
}
